  const wide = v.W > 15500;
  if (wide) { place("south", 62, 84, true); place("north", 62, 174, true); place("west", 268, 84, false); place("east", 268, 174, false); }
  else { place("south", 62, 88, true); place("north", 240, 88, false); place("east", 62, 198, true); place("west", 196, 198, false); }
  const lg = el("g", { "data-block": "materials", transform: wide ? "translate(62 224)" : "translate(322 135)" }, svg);
